const row=(cols,cards,f=1)=>{const keep=cards.map((x,i)=>[x,i]).filter(([x])=>x!==''&&x!=null);if(!keep.length)return '';if(keep.length!==cards.length){const cc=String(cols).trim().split(/\s+/);cols=cc.length===cards.length?keep.map(([,i])=>cc[i]).join(' '):`repeat(${keep.length},minmax(0,1fr))`;cards=keep.map(([x])=>x)}return `<div class="row" style="grid-template-columns:${cols};--f:${f}">${cards.join('')}</div>`};
const fit=(...parts)=>`<div class="fit">${parts.filter(Boolean).join('')}</div>`;
