const clickRow=(r,act)=>{r.__click=act;return r};
/* ---------- decisions ("Needs a decision") ---------- */
function decide(list){if(!list||!list.length)return '';const L=list.slice(0,3);return `<div class="decide auto"><b>${ico('check','style="width:15px;height:15px"')}Needs a decision</b>${L.map((d,i)=>{const k=S.mod+(S.mod==='apm'?S.apmCat:'')+':'+i;const dn=UI.done[k];return `<div class="dcard ${dn?'done':''}"><span class="dot" style="background:var(--${d.s||'warn'})"></span>${esc(d.t)}${dn?`<span class="chip c-ok">${esc(dn)}</span>`:d.a.map(a=>`<button class="btn sm ${a===d.a[0]?'':'ghost'}" onclick="doDecide('${k}','${q(a)}','${q(d.t)}')">${esc(a)}</button>`).join('')}</div>`}).join('')}</div>`}
function doDecide(k,a,t){UI.done[k]=a==='Acknowledge'?'Acknowledged':a+' done';toast(a+': '+t);renderView()}
/* ---------- assets ---------- */
const TAGP={apm:'FS',ems:'EM',pqi:'PQ',derms:'DR',ums:'UT',oee:'LN',qi:'QC',tele:'VH',dt:'DT',inv:'SK',sus:'CB',edge:'GW'};
function rngOf(p){let [n,v,u,lo,hi]=p;const x=parseFloat(v);if(isNaN(x))return null;if(lo==null&&hi==null){if(x<=0)return null;return [0,+(x*1.6).toFixed(2),false]}if(lo==null)return [0,hi,true];return [lo,hi,true]}
function rdState(p){const r=rngOf(p);if(!r||!r[2])return '';const x=parseFloat(p[1]);if(x<r[0]||x>r[1])return 'bad';const span=r[1]-r[0];if(x<r[0]+span*.06||x>r[1]-span*.06)return 'wrn';return ''}
const ICMAP=[[/tanker/i,'p_tanker'],[/tipper|truck/i,'p_truck'],[/forklift/i,'p_fork'],[/shuttle|bus/i,'p_bus'],[/pickup/i,'p_pickup'],[/diesel storage|tank t-01/i,'p_atgd'],[/petrol storage|t-02/i,'p_atgp'],[/safety tag|worker/i,'p_wtag'],[/rfid/i,'p_rfid'],[/gps|tracker/i,'p_gps'],[/main incomer/i,'p_incomer'],[/capacitor/i,'p_capbank'],[/bus coupler/i,'p_buscoupler'],[/sub-feeder|feeder/i,'p_feeder'],[/pq meter/i,'p_pqmeter'],[/harmonic/i,'p_harm'],[/flicker/i,'p_flicker'],[/solar inverter/i,'p_solar'],[/wind/i,'p_wind'],[/bess|battery storage/i,'p_bess'],[/dg set/i,'p_dg'],[/ev charger/i,'p_ev'],[/water pump/i,'p_wpump'],[/air compressor/i,'p_comp'],[/boiler/i,'p_boiler'],[/fuel tank/i,'p_ftank'],[/gas supply/i,'p_gas2'],[/camera/i,'p_cam'],[/drone/i,'p_drone'],[/crawler/i,'p_crawler'],[/quadruped/i,'p_quad'],[/ar smart/i,'p_ar'],[/vr training/i,'p_vr'],[/^line \d/i,'p_line'],[/pump house twin/i,'p_tw_pump'],[/tank farm twin/i,'p_tw_tank'],[/hydrant yard twin/i,'p_tw_hyd'],[/control room twin/i,'p_tw_ctrl'],[/grid electricity/i,'p_grid'],[/boiler fuel/i,'p_bfuel'],[/diesel \(dg\)/i,'p_dg'],[/solar offset/i,'p_solar'],[/pump seals/i,'p_seal'],[/gateway/i,'p_gateway'],[/protocol converter/i,'p_conv'],[/buffer/i,'p_buffer']];
function icFor(n,ic){if(IC[ic]&&/^(u_|tank|pump|hyd|spr|hose|facp|smk|heat|ext|gas|mon|pnl|jky|bst|dsl)/.test(ic))return ic;const h=ICMAP.find(x=>x[0].test(n));return h?h[1]:(IC[ic]?ic:'u_g_plc')}
function mkA(src,modk,i,cat){src={...src,ic:icFor(src.n,src.ic)};const a={id:modk+':'+(cat||'')+':'+i,mod:modk,cat,i,n:src.n,ic:src.ic,st:src.st,hl:src.hl||'',loc:src.loc,tag:(cat?(CATB[cat]?CATB[cat].short.slice(0,3).toUpperCase().replace(/[^A-Z]/g,'X'):'AS'):TAGP[modk]||'AS')+'-'+String(i+1).padStart(2,'0'),ps:(src.ps||[]).map(p=>[p[0],p[1],p[2]||'',p[3],p[4]]),subs:(src.subs||[]).map((s,j)=>({n:s[0],ic:s[1],par:s[2],j}))};
 if(/Alarm|Critical/.test(a.st)){a.hl='Critical';a.st='Running'}if(a.st==='Warning'){a.hl='Warning';a.st='Running'}if(a.st==='Normal'&&modk!=='apm')a.st='Running';
 if(!a.hl&&a.ps.some(p=>rdState(p)==='bad'))a.hl='Warning';a.health=a.hl==='Critical'?56:a.hl==='Warning'?74:Math.round(86+rnd(a.n)*12);return a}
/* Fire & Safety: R4 assets with R7 ranges */
const FRNG={Pressure:[5,14],Level:[60,100],'Fuel level':[50,100],Battery:[24,28.8],'Engine temp':[0,95],Temp:[0,70],Current:[0,10],Discharge:[5,12],Flow:[0,1500],RPM:[0,1800]};
const FSUB={tank:1,pump:0,jky:0,bst:0,dsl:0,hyd:2,hose:5,mon:2,spr:3,facp:4,smk:4,heat:4,ext:5,gas:5,pnl:0};
function fireAssets(){return DATA.AS.map((a,i)=>{let ps=[];if(a.un){ps=a.un[0][2].map(p=>[p[0],String(p[1]),p[2]]);ps.push(['Standby unit',a.un[1][1],''])}else ps=a.v.map(p=>[p[0],String(p[1]),p[2]||'']);
 ps=ps.map(p=>{const r=(a.id==='spr'&&p[0]==='Pressure')?[3.5,10]:(a.id==='mon'&&p[0]==='Flow')?[0,2400]:FRNG[p[0]];return r&&!isNaN(parseFloat(p[1]))?[p[0],p[1],p[2],r[0],r[1]]:[p[0],p[1],p[2],null,null]});
 let st=a.st==='Normal'?'Monitoring':a.st;let hl=a.id==='hyd'?'Critical':a.id==='smk'?'Warning':'';
 const g=DATA.FIREG[FSUB[a.id]||0];const subs=a.un?a.un.map(u=>[u[0]+' unit',a.id==='jky'?'u_f_jky':'u_f_pump',u[2][0][0]]).concat(g.subs.slice(-2)):g.subs.slice(0,4);
 const A=mkA({n:a.n,ic:a.id,st,hl,loc:'Fire & Safety',ps,subs},'apm',i,'apm');A.fid=a.id;return A})}
let CACHE={};
function assetsOf(m,cat){const k=m+':'+(m==='apm'?(cat||S.apmCat):'')+':'+S.plant;if(CACHE[k])return CACHE[k];let L=[];
 if(m==='apm'){const c=cat||S.apmCat;if(c==='apm')L=fireAssets();else L=UCB[c].mains.map((x,i)=>mkA(x,'apm',i,c))}
 else{const src=DATA.MOD[m==='carbon'?'sus':m==='twin'?'dt':m]||[];L=src.map((x,i)=>mkA(x,m,i))}
 const f=P().f;if(f!==1)L.forEach(a=>a.ps.forEach(p=>{const x=parseFloat(p[1]);if(!isNaN(x)&&!/%|°C|Hz|V$|count|rpm/.test(p[2])&&x>5)p[1]=String(+(x*f).toFixed(x<50?1:0))}));
 CACHE[k]=L;return L}
function findA(id){const [m,c,i]=id.split(':');return assetsOf(m,c||undefined)[+i]}
function subOf(a,j){const s=a.subs[j];const r=rnd(a.n+j);const st=j===0&&a.hl?a.hl:(r<.08?'Warning':'');const base=10+r*90;const unit=/temp/i.test(s.par)?'°C':/press/i.test(s.par)?'bar':/vibr/i.test(s.par)?'mm/s':/current/i.test(s.par)?'A':/level|charge|signal/i.test(s.par)?'%':'';
 const v=unit==='°C'?(40+r*45):unit==='bar'?(3+r*9):unit==='mm/s'?(0.8+r*3.5):unit==='A'?(4+r*40):unit==='%'?(60+r*38):Math.round(base);
 return {n:s.n,ic:s.ic,par:s.par,st:'Running',hl:st,v:fmtN(+v.toFixed(1)),u:unit,hh:st==='Critical'?58:st==='Warning'?76:Math.round(86+r*12)}}
function opChip(a){return chip(a.st)+(a.hl?chip(a.hl):'')}
function keyR(a,n=3){return a.ps.slice(0,n)}
function readCard(a,p){const [v,u]=conv(p[1],p[2]);const r=rngOf(p),st=rdState(p);let bar='';
 if(r){const x=parseFloat(p[1]),pc=Math.max(0,Math.min(100,(x-r[0])/(r[1]-r[0]||1)*100));bar=`<div class="rng" title="Normal range ${r[0]} to ${r[1]} ${esc(p[2])}"><span style="width:${pc}%;background:var(--${st==='bad'?'crit':st==='wrn'?'warn':'ok'});opacity:.55"></span><i style="left:calc(${pc}% - 2px)"></i></div>${r[2]?`<div class="rngl"><span>${r[0]}</span><span>${r[1]}</span></div>`:''}`}
 return `<div class="krc ${st}" onclick="openPanel('${a.id}')" title="${esc(a.n)}: ${esc(p[0])}"><div class="kh"><span>${esc(p[0])}</span>${spark(series(a.n+p[0],10,50,12),st==='bad'?'var(--crit)':'var(--brand)',46,14)}</div><b>${v} <em>${esc(u)}</em></b>${bar}<div class="kh"><span>${esc(a.n)}</span></div></div>`}
function keyBoard(L,max=9,cols=3){const R=[];L.forEach(a=>keyR(a,2).forEach(p=>{if(!isNaN(parseFloat(p[1])))R.push([a,p])}));R.sort((x,y)=>(rdState(y[1])==='bad')-(rdState(x[1])==='bad'));return `<div class="kr" style="--kc:${cols}">${R.slice(0,max).map(x=>readCard(x[0],x[1])).join('')}</div>`}
function acard(a){const p=a.ps[0]||['','',''];const [v,u]=conv(p[1],p[2]);return `<button class="acd ${a.hl?'u-'+a.hl:''}" onclick="openPanel('${a.id}')" aria-label="${esc(a.n)}, ${esc(a.st)}"><span class="pic">${pic(a.ic)}</span><span class="ab"><b>${esc(a.n)}</b><span class="chs">${opChip(a)}</span><span class="av2">${v} <small>${esc(u)} ${esc(p[0])}</small></span>${a.ps.slice(1,3).length?`<span class="p2">${a.ps.slice(1,3).map(x=>{const c=conv(x[1],x[2]);return `${esc(x[0])} <b>${c[0]} ${esc(c[1])}</b>`}).join('<br>')}</span>`:''}</span></button>`}
function scard(a,s,j){return `<button class="acd ${s.hl?'u-'+s.hl:''}" onclick="openPanel('${a.id}',${j})"><span class="pic">${pic(s.ic)}</span><span class="ab"><b>${esc(s.n)}</b><span class="chs">${chip(s.st)}${s.hl?chip(s.hl):''}</span><span class="av2">${s.v} <small>${esc(s.u)} ${esc(s.par)}</small></span><span class="p2">Operating hours today <b>${(4+rnd(s.n+a.n)*5).toFixed(1)} h</b></span></span></button>`}
/* ---------- alarms ---------- */
let ALM=null;
function buildAlarms(){const L=[];let id=1;const add=(m,cat,a,msg,sev,t,ai)=>L.push({id:id++,m,cat,a,msg,sev,t,st:'Active',ai});
 add('apm','apm','Hydrant System','Low pressure at remote hydrant, 4.8 bar','Critical','10:40');add('apm','apm','Smoke Detector','Detector fault, winding shop','Warning','09:05');add('apm','apm','Water Tank Level','Level below 70% after hydrant test','Warning','09:45');
 DATA.UC.forEach(u=>{const As=UCB[u.k].mains;u.alarms.forEach(x=>add('apm',u.k,(As[x[2]]||As[0]).n,x[0],x[1]==='High'?'Critical':x[1]==='Medium'?'Warning':'Info',x[3]))});
 [['ems','Sub-feeder 1 · Compressor house','Power factor below 0.95','Warning','08:40'],['ems','Main incomer','Demand at 91% of contract','Warning','11:05'],['pqi','Feeder 2 PQ meter','Voltage sag 18% for 120 ms','Warning','06:12'],['pqi','Incomer PQ meter','Current THD 5.4% rising','Info','09:15'],['derms','Battery storage (BESS)','Cell temperature 34 °C near limit','Warning','10:50'],['ums','Air compressor','Air leakage estimate above 10%','Warning','09:10'],['ums','Fuel tank','Consumption 3% over budget','Info','07:40'],['tele','Fuel tanker TNK-02','Fuel drop of 62 L in 10 min, ignition off','Critical','11:18'],['tele','Tipper truck TRK-01','Harsh braking, 3 events','Warning','10:22'],['tele','Staff shuttle BUS-04','Left geofence, Main gate','Info','10:02'],['oee','Line 2','Unplanned stop 18 min','Warning','10:30'],['oee','Line 3','Changeover over standard by 13 min','Info','09:40'],['inv','Nozzle heads','Stock 14 below reorder level 21','Warning','09:10'],['inv','RFID gate 2','Read rate 91%, below 98%','Warning','08:52'],['qi','Camera 1 · Pump house','Scratch defects up 40% this hour','Warning','10:55'],['qi','Inspection drone D-01 · Tank farm roof','Corrosion found on Tank 2 shell','Critical','11:02'],['twin','Hydrant yard twin','Sync latency 8.5 s, limit 5 s','Warning','09:58'],['fin','Receivables','4 invoices overdue beyond 90 days','Critical','08:00'],['carbon','Grid electricity','Monthly emissions 6% over target','Warning','08:00']].forEach(x=>add(x[0],null,x[1],x[2],x[3],x[4]));
 return L}
function alarmsFor(m){if(!ALM)ALM=buildAlarms();const sel=S.mods;if(m==='dash')return ALM.filter(a=>sel.includes(a.m)&&(a.m!=='apm'||S.uc.includes(a.cat)));if(m==='apm')return ALM.filter(a=>a.m==='apm'&&a.cat===S.apmCat);return ALM.filter(a=>a.m===m)}
const actCount=m=>alarmsFor(m).filter(a=>a.st==='Active').length;
function ack(id){const a=ALM.find(x=>x.id===id);if(a){a.st='Acknowledged';toast('Acknowledged: '+a.a)}renderView();renderRail()}
function alarmRows(m,n=4){const L=alarmsFor(m).filter(a=>a.st==='Active').sort((a,b)=>(a.sev==='Critical'?0:a.sev==='Warning'?1:2)-(b.sev==='Critical'?0:b.sev==='Warning'?1:2)).slice(0,n);
 return L.length?`<div class="rows">${L.map(x=>`<div class="rw"><div class="a"><b>${esc(x.a)}</b><small>${m==='dash'?esc(mod(x.m).s)+(x.cat&&x.m==='apm'?' - '+esc(CATB[x.cat].short):'')+' · ':''}${esc(x.msg)}</small></div><span class="v" style="font-size:11px;color:var(--mut)">${x.t}</span>${chip(x.sev)}</div>`).join('')}</div>`:'<div class="empty">No active alarms. Everything is within limits.</div>'}
/* ---------- side panel (same as APM everywhere) ---------- */
function openPanel(id,j){UI.panel={id,j:j==null?null:j};renderPanel()}
function closePanel(){UI.panel=null;renderPanel()}
function renderPanel(){const d=document.getElementById('drw'),sc=document.getElementById('scrim');if(!UI.panel){d.classList.remove('on');sc.classList.remove('on');return}
 const a=findA(UI.panel.id);if(!a){closePanel();return}const j=UI.panel.j;let h='';const cl=`<button class="dr-x" onclick="closePanel()" aria-label="Close">${ico('chevr')}</button>`;
 if(j!=null){const s=subOf(a,j);h=`<div class="dr-top"><span class="pic lg">${pic(s.ic)}</span><div class="t"><b>${esc(s.n)}</b><small>Part of ${esc(a.n)}</small><div class="chs" style="margin-top:6px">${chip(s.st)}${s.hl?chip(s.hl):''}</div></div>${cl}</div>
  <div class="pk-t"><div><small>Health</small><b>${s.hh}</b></div><div><small>${esc(s.par)}</small><b>${s.v} <span style="font-size:12px">${esc(s.u)}</span></b></div><div><small>Next service</small><b>${12+hs(s.n)%30} d</b></div></div>
  <div class="dr-h">Key reading trend, 24 h</div>${chart({labels:['00','04','08','12','16','20','now'],series:[{name:s.par,type:'area',color:'var(--brand)',values:series(s.n+a.n,7,50,10)}],h:150})}
  <div class="dr-h">Other sub assets of ${esc(a.n)}</div><div class="sbl2">${a.subs.map((x,k)=>k===j?'':(()=>{const z=subOf(a,k);return `<button class="sbr" onclick="openPanel('${a.id}',${k})"><span class="pic">${pic(z.ic)}</span><span class="st"><b>${esc(z.n)}</b><small>${esc(z.par)}: ${z.v} ${esc(z.u)}</small></span>${chip(z.st)}</button>`})()).join('')}</div>
  <div class="dr-act"><button class="btn ghost" onclick="openPanel('${a.id}')">${esc(a.n)}</button><button class="btn" onclick="askAsset('${a.id}')">Ask AI</button></div>`}
 else{const al=alarmsFor(a.mod).filter(x=>x.a===a.n&&x.st==='Active');const docs=docsOf(a);
  h=`<div class="dr-top"><span class="pic lg">${pic(a.ic)}</span><div class="t"><b>${esc(a.n)}</b><small>${esc(a.tag)} · ${esc(a.loc)}</small><div class="chs" style="margin-top:6px">${opChip(a)}</div></div>${cl}</div>
  <div class="pk-t"><div><small>Health</small><b style="color:var(--${a.health<70?'crit':a.health<85?'warn':'ok'})">${a.health}</b></div><div><small>Criticality</small><b>${a.health<70?'A':a.health<85?'B':'C'}</b></div><div><small>Next service</small><b>${a.hl?'Overdue':(9+hs(a.n)%40)+' d'}</b></div></div>
  <div class="dr-h">Key readings</div><div class="kr" style="--kc:2">${a.ps.slice(0,4).map(p=>readCard(a,p)).join('')}</div>
  ${al.length?`<div class="dr-h">Alarms</div><div class="rows">${al.map(x=>`<div class="rw"><div class="a"><b style="white-space:normal">${esc(x.msg)}</b><small>${x.t}</small></div>${chip(x.sev)}<button class="btn sm ghost" onclick="ack(${x.id})">Acknowledge</button></div>`).join('')}</div>`:''}
  <div class="dr-h">Maintenance and compliance</div><div class="dr-kv"><div><small>Next predicted service</small><b>${a.hl?'Overdue, predictive':'in '+(9+hs(a.n)%40)+' days'}</b></div><div><small>Remaining useful life</small><b>${a.hl?(a.hl==='Critical'?'about 12 days':'about 30 days'):'over 90 days'}</b></div><div><small>Documents</small><b>${docs.length} · ${docs.filter(d=>d.st!=='Valid').length} to renew</b></div><div><small>Last inspection</small><b>${10+hs(a.tag)%60} days ago, passed</b></div></div>
  ${a.subs.length?`<div class="dr-h">Sub assets · ${a.subs.length}</div><div class="sbl2">${a.subs.map((x,k)=>{const z=subOf(a,k);return `<button class="sbr" onclick="openPanel('${a.id}',${k})"><span class="pic">${pic(z.ic)}</span><span class="st"><b>${esc(z.n)}</b><small>${esc(z.par)}: ${z.v} ${esc(z.u)}</small></span>${chip(z.st)}${z.hl?chip(z.hl):''}</button>`}).join('')}</div>`:''}
  <div class="dr-act"><button class="btn ghost" onclick="askAsset('${a.id}')">Ask AI</button><button class="btn" onclick="open360('${a.id}')">View 360</button></div>`}
 d.innerHTML=h;d.classList.add('on');sc.classList.add('on')}
