function view360(){const a=findA(UI.v360);if(!a){UI.v360=null;return renderModule()}const t=UI.v3t;const al=alarmsFor(a.mod).filter(x=>x.a===a.n);
 const hdr=`<div class="card auto"><div class="v3h"><button class="btn ghost sm" onclick="back()">${ico('back','style="width:14px;height:14px;vertical-align:-3px"')} Back</button><span class="pic lg">${pic(a.ic)}</span><div class="t"><b>${esc(a.n)}</b><small>${esc(a.tag)} · ${esc(a.loc)} · View 360</small></div><div class="hs"><b>${a.health}</b>Health</div>${opChip(a)}<span class="chip c-ok">● Live</span><button class="btn ghost" onclick="askAsset('${a.id}')">Ask AI</button><button class="btn" onclick="openAdd('doc',{asset:'${q(a.n)}',mod:'${a.mod}'})">+ Add document</button></div><div class="subchips" style="margin-top:12px;display:inline-flex">${V3T.map(x=>`<button class="${t===x[0]?'on':''}" onclick="UI.v3t='${x[0]}';renderView()">${x[1]}${x[0]==='al'&&al.filter(z=>z.st==='Active').length?` · ${al.filter(z=>z.st==='Active').length}`:''}</button>`).join('')}</div></div>`;
 let body='';
 if(t==='det')body=row('1.4fr 1fr',[gcard('Key readings',`<div class="kr" style="--kc:3">${a.ps.map(p=>readCard(a,p)).join('')}</div>`),gcard('Main reading, last 24 h',chart({labels:['00','02','04','06','08','10','12','14','16','18','20','22'],series:[{name:a.ps[0]?a.ps[0][0]:'Value',type:'area',color:'var(--brand)',values:series(a.n,12,parseFloat(a.ps[0]&&a.ps[0][1])||50,6)}],band:rngOf(a.ps[0]||[])&&rngOf(a.ps[0])[2]?rngOf(a.ps[0]).slice(0,2):null,h:220}),{sub:a.ps[0]?esc(a.ps[0][0]):''})],1.3)+row('1fr 1fr 1fr',[gcard('Identity',`<div class="kv3"><div><small>Asset tag</small><b>${esc(a.tag)}</b></div><div><small>Area</small><b>${esc(a.loc)}</b></div><div><small>Make / model</small><b>${['Kirloskar','Siemens','ABB','Schneider','Delta'][hs(a.n)%5]} ${String(100+hs(a.n)%900)}</b></div><div><small>Installed</small><b>${2018+hs(a.tag)%7}</b></div></div>`),gcard('Connectivity',`<div class="kv3"><div><small>Edge gateway</small><b>Edge-${P().code}-0${1+hs(a.n)%3}</b></div><div><small>Protocol</small><b>${['Modbus TCP','OPC UA','Modbus RTU','MQTT'][hs(a.n)%4]}</b></div><div><small>Last data</small><b>2 s ago</b></div><div><small>Data quality</small><b>Good</b></div></div>`),gcard('Sub assets',a.subs.length?`<div class="sbl2">${a.subs.slice(0,5).map((x,k)=>{const z=subOf(a,k);return `<button class="sbr" onclick="openPanel('${a.id}',${k})"><span class="pic">${pic(z.ic)}</span><span class="st"><b>${esc(z.n)}</b><small>${esc(z.par)}: ${z.v} ${esc(z.u)}</small></span>${chip(z.st)}</button>`}).join('')}</div>`:'<div class="empty">No sub assets.</div>')]);
 if(t==='live')body=row('1fr',[gcard('Live data',tbl(['Parameter','Value','Unit','Normal range','Status','Last hour'],a.ps.map(p=>{const c=conv(p[1],p[2]),r=rngOf(p),st=rdState(p);return [`<b>${esc(p[0])}</b>`,`<b>${c[0]}</b>`,esc(c[1]),r&&r[2]?`${r[0]} to ${r[1]}`:'-',st==='bad'?chip('Critical'):st==='wrn'?chip('Warning'):chip('Normal'),spark(series(a.n+p[0],12,50,12),st==='bad'?'var(--crit)':'var(--brand)')]}),['','r','','','','']),{sub:'Refreshed every '+S.refresh+' s'})]);
 if(t==='mnt'){const rul=a.hl==='Critical'?12:a.hl==='Warning'?30:96;body=row('1fr 1fr 1fr',[gcard('Predictive maintenance',`<div class="big" style="color:var(--${rul<20?'crit':rul<45?'warn':'ok'})">${rul} days</div><div class="note">Estimated remaining useful life from vibration, temperature and run-hour trends.</div><div class="hb"><b>Health</b><div class="tr"><span style="width:${a.health}%;background:var(--${a.health<70?'crit':a.health<85?'warn':'ok'})"></span></div><div class="r">${a.health}</div></div>`),gcard('Service',`<div class="rows"><div class="rw"><div class="a"><b>Next predicted service</b><small>Window opens</small></div><span class="v">${a.hl?'Now':'in '+(9+hs(a.n)%40)+' d'}</span></div><div class="rw"><div class="a"><b>Last service</b><small>Maintenance team</small></div><span class="v">${1+hs(a.n)%27} Sep 2026</span></div><div class="rw"><div class="a"><b>Spares ready</b><small>From Smart Inventory</small></div>${chip(hs(a.n)%4?'Good':'Watch')}</div></div>`),gcard('Recommended action',`<div class="rows">${(a.hl?['Inspect '+(a.subs[0]?a.subs[0].n.toLowerCase():'the asset')+' at the next stop','Keep the standby unit ready','Order spares before the window opens']:['No action needed now','Keep the current inspection plan']).map(x=>`<div class="rw"><div class="a"><b style="white-space:normal;font-weight:600">${esc(x)}</b></div></div>`).join('')}</div><div style="margin-top:10px"><button class="btn sm" onclick="openAdd('task',{asset:'${q(a.n)}',mod:'${a.mod}'})">+ Add maintenance task</button></div>`)]);}
 if(t==='doc'){const D=docsOf(a);body=row('1.6fr 1fr',[gcard('Documents',tbl(['Document','Type','Valid till','Status'],D.map(d=>[`<b>${esc(d.t)}</b>${d.rid?' <span class="chip c-info">Added</span>':''}`,esc(d.ty),d.ex||'-',chip(d.st)])),{extra:`<button class="btn sm" onclick="openAdd('doc',{asset:'${q(a.n)}',mod:'${a.mod}'})">+ Add document</button>`}),gcard('Compliance',`<div class="rows">${[['Statutory inspection','Passed, '+(20+hs(a.n)%60)+' days ago','Valid'],['Calibration',D.find(x=>/Calib/.test(x.ty))?D.find(x=>/Calib/.test(x.ty)).st:'Valid',D.find(x=>/Calib/.test(x.ty))?D.find(x=>/Calib/.test(x.ty)).st:'Valid'],['Safety checks','All done this month','Valid']].map(x=>`<div class="rw"><div class="a"><b>${x[0]}</b><small>${x[1]}</small></div>${chip(x[2])}</div>`).join('')}</div>`)]);}
 if(t==='al')body=row('1fr',[gcard('Alarms for this asset',al.length?tbl(['Time','Alarm','Severity','State',''],al.map(x=>[x.t,esc(x.msg),chip(x.sev),chip(x.st),x.st==='Active'?`<button class="btn sm" onclick="ack(${x.id})">Acknowledge</button>`:''])):'<div class="empty">No alarms for this asset in the last 30 days.</div>')]);
 return fit(hdr,body)}
/* ---------- R7 style full screen expand ---------- */
function fsEnter(){UI.exp=true;document.body.classList.add('fs');renderView()}
function fsExit(){UI.exp=false;document.body.classList.remove('fs');renderView()}
function fsView(){const m=S.mod,L=assetsOf(m);const t=m==='apm'?apmTiles():tiles(modTiles(m));
 const body=UI.expSub?L.map(a=>`<div class="grp">${acard(a)}<div class="gsub"><b>Sub assets <small>${a.subs.length} sub assets · ${a.subs.filter((s,j)=>subOf(a,j).hl).length} need attention</small></b><div class="sg">${a.subs.map((s,j)=>scard(a,subOf(a,j),j)).join('')||'<span class="empty">No sub assets</span>'}</div></div></div>`).join(''):`<div class="ag" style="--ac:5">${L.map(acard).join('')}</div>`;
 return `<div style="display:flex;flex-direction:column;gap:var(--gap)"><div class="fsbar"><b>Assets <span class="cnt">${L.length}</span> · ${m==='apm'?'APM-'+esc(CATB[S.apmCat].short):esc(mod(m).s)}</b><span style="color:var(--mut);font-size:12px">Press Esc to go back</span><button class="xb" onclick="fsExit()" title="Collapse to the overview" aria-label="Collapse">${ico('collapse')}</button></div>${t}<div><div class="fsub" role="tablist"><button class="${UI.expSub?'':'on'}" onclick="UI.expSub=false;renderView()">Main assets</button><button class="${UI.expSub?'on':''}" onclick="UI.expSub=true;renderView()">Main and sub assets</button></div></div>${body}${gcard('Active alarms',alarmRows(m,6),{x:false})}</div>`}

/* ===================== shell, navigation, common tabs ===================== */
const MODV={};/* module registry: {subs:()=>[[id,label]], view:(sub)=>html, assets:bool} */
function snap(){return {mod:S.mod,tab:S.tab,page:S.page,sub:S.sub[S.mod]||null,v360:UI.v360,etab:UI.etab,stab:UI.stab}}
function go(ch){const b=snap();Object.assign(S,ch);if('mod' in ch||'tab' in ch||'page' in ch){UI.v360=null}const a=snap();if(JSON.stringify(b)!==JSON.stringify(a))UI.hist.push(b);if(UI.hist.length>50)UI.hist.shift();closeMenus();closePanel();if(UI.exp)fsExit();render();const v=document.getElementById('view');if(v)v.scrollTop=0}
function back(){const h=UI.hist.pop();if(!h)return;S.mod=h.mod;S.tab=h.tab;S.page=h.page;if(h.sub)S.sub[h.mod]=h.sub;UI.v360=h.v360;UI.etab=h.etab||'ov';UI.stab=h.stab||'look';closePanel();render()}
function goSub(id){UI.hist.push(snap());S.sub[S.mod]=id;UI.v360=null;closePanel();render()}
function closeMenus(){document.querySelectorAll('.menu.open').forEach(m=>m.classList.remove('open'))}
function toggleMenu(id,e){e.stopPropagation();const m=document.getElementById(id);const w=m.classList.contains('open');closeMenus();if(!w)m.classList.add('open')}
document.addEventListener('click',closeMenus);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.getElementById('modal').classList.contains('show'))closeModal();else if(UI.panel)closePanel();else if(UI.exp)fsExit();else if(document.body.classList.contains('focus'))setFocus(false);closeMenus()}});
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),2400)}
function openModal(h,narrow){const m=document.getElementById('modal');m.innerHTML=`<div class="card ${narrow?'narrow':''}" onclick="event.stopPropagation()">${h}</div>`;m.classList.add('show')}
function closeModal(){document.getElementById('modal').classList.remove('show')}
function setFocus(on){document.body.classList.toggle('focus',on);document.body.classList.toggle('fs',on||UI.exp);if(on)toast('Control-room view. Press Esc to exit')}
const visibleMods=()=>MODULES.filter(m=>S.mods.includes(m.id));
const subsOf=m=>(MODV[m]&&MODV[m].subs?MODV[m].subs():[]);
function curSub(m){const L=subsOf(m);const s=S.sub[m];return L.find(x=>x[0]===s)?s:(L[0]?L[0][0]:null)}
function validState(){if(S.mod!=='dash'&&!S.mods.includes(S.mod))S.mod='dash';if(S.mod==='apm'&&!S.uc.includes(S.apmCat))S.apmCat=S.uc[0]||'apm';const T=tabsOf(S.mod).map(t=>t[0]);if(!T.includes(S.tab))S.tab='ov'}
function tabsOf(m){if(m==='dash')return [['ov','Overview','dash'],['alarms','Alarms & Events','alarms'],['reports','Reports & Forecasting','reports'],['ai','AI Co-Pilot','ai']];const L=[['ov','Overview','dash']];if(mod(m).assets)L.push(['assets','Assets','assets']);L.push(['alarms','Alarms & Events','alarms'],['reports','Reports & Forecasting','reports'],['ai','AI Co-Pilot','ai']);return L}
/* theme / palette like R7 */
function applyTheme(){const r=document.documentElement;r.dataset.theme=S.theme;r.dataset.density=S.density;const p=PL[S.theme][S.pal[S.theme]]||Object.values(PL[S.theme])[0];r.style.setProperty('--page',p.bg);r.style.setProperty('--acc',p.ac);r.style.setProperty('--ac2',p.ac2);r.style.setProperty('--ac3',p.ac3);r.style.setProperty('--brand',p.brand)}
function setTheme(t){S.theme=t;render()}
function setPal(k){S.pal[S.theme]=k;render()}
function edgeInfo(){const off=S.plant==='Mumbai Plant';return {off,txt:off?'Edge: 2 of 3 connected':'Edge: all connected',color:off?'var(--crit)':'var(--ok)'}}
function renderHdr(){const N=alarmsFor('dash').filter(a=>a.st==='Active').slice(0,6);
 document.getElementById('hdr').innerHTML=`<div class="brand"><div class="logo"><i></i></div><div><b>CoreOT</b><small>by PlantEdge Technosolutions</small></div></div>
 ${UI.hist.length?`<button class="ibtn" onclick="back()" title="Back" aria-label="Back">${ico('back')}</button>`:''}<div class="spacer"></div>
 <div class="live"><span class="pulse"></span><span id="ago">Live, updated just now</span></div>
 <div class="dd"><button class="ibtn" onclick="toggleMenu('mBell',event)" aria-label="Notifications">${ico('bell')}${N.length?'<span class="bd"></span>':''}</button><div class="menu" id="mBell" style="min-width:330px" onclick="event.stopPropagation()"><div class="mh"><b>Notifications</b><small>${N.length} need attention</small></div>${N.map(a=>`<button class="mi" style="align-items:flex-start" onclick="goAlarm('${a.m}','${a.cat||''}')"><span style="flex:1;min-width:0"><b style="font-size:13px">${esc(a.a)}</b><br><small style="color:var(--mut)">${esc(mod(a.m).s)} · ${esc(a.msg)}</small></span><small style="color:var(--mut)">${a.t}</small></button>`).join('')}<button class="mi" style="justify-content:center;font-weight:700" onclick="go({mod:'dash',tab:'alarms',page:null})">View all alarms</button></div></div>
 <button class="ibtn" onclick="setFocus(true)" title="Control-room view" aria-label="Control-room view">${ico('tv')}</button>
 <select class="sel" aria-label="Plant" onchange="S.plant=this.value;CACHE={};render();toast(this.value+' selected')">${Object.keys(PLANTS).map(p=>`<option ${p===S.plant?'selected':''}>${p}</option>`).join('')}</select>
 <div class="clock" id="clock"></div>
 <div class="dd"><button class="prof" onclick="toggleMenu('mProf',event)" aria-label="Account menu"><span class="av">${esc(R8INI())}</span><span class="nm" style="font-weight:700;font-size:13px">${esc(R8ME())}</span>${ico('chev','style="width:15px;height:15px"')}</button>
 <div class="menu" id="mProf" onclick="event.stopPropagation()"><div class="mh"><b>${esc(R8ME())}</b><small>${esc(R8MAIL())} · Demo</small></div>
 <button class="mi" onclick="go({page:'edge'})">${ico('edge')}Edge Status<span class="dot" style="margin-left:auto;background:${edgeInfo().color}"></span></button>
 <button class="mi" onclick="UI.stab='look';go({page:'settings'})">${ico('cog')}Settings</button>
 <button class="mi" onclick="go({page:'malerts'})">${ico('phone')}Mobile alerts</button>
 <button class="mi" onclick="go({page:'help'})">${ico('help')}Help & Support</button>
 <button class="mi" onclick="go({page:'profile'})">${ico('user')}Profile</button><hr>
 <button class="mi" style="color:var(--crit)" onclick="document.getElementById('out').classList.add('show')">${ico('logout')}Log Out</button></div></div>`;tick()}
function goAlarm(m,cat){if(m==='apm'&&cat)S.apmCat=cat;go({mod:m,tab:'alarms',page:null})}
function tick(){const el=document.getElementById('clock');if(!el)return;const d=new Date();el.innerHTML=`<b>${d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</b>${d.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric'})}`}
function renderModbar(){const el=document.getElementById('modbar');const col=S.bar==='closed';el.classList.toggle('collapsed',col);const on=id=>!S.page&&S.mod===id;
 let h=`<button class="mchip ${on('dash')?'on':''}" onclick="go({mod:'dash',tab:'ov',page:null})" title="Dashboard - all selected modules"><span class="ic">${ico('grid')}</span>Dashboard</button>`;
 visibleMods().forEach(m=>{if(m.id==='apm'){const cur=CATB[S.apmCat];h+=`<span class="dd apmdd"><button class="mchip ${on('apm')?'on':''}" onclick="toggleMenu('mApm',event)" title="APM - ${esc(cur.name)}" aria-haspopup="menu"><span class="ic">${ico('apm')}</span>APM${on('apm')?' - '+esc(cur.short):''}${ico('chev','style="width:13px;height:13px"')}</button><div class="menu apmmenu" id="mApm" onclick="event.stopPropagation()"><div class="mh"><b>APM categories</b><small>${S.uc.length} of ${CAT.length} selected on the Dashboard</small></div><div class="catg">${CAT.filter(x=>S.uc.includes(x.k)).map(x=>`<button class="mi ${S.apmCat===x.k&&on('apm')?'on':''}" onclick="setCat('${x.k}')"><span class="cti">${x.i}</span>${esc(x.short)}</button>`).join('')}</div></div></span>`;return}
  h+=`<button class="mchip ${on(m.id)?'on':''}" onclick="go({mod:'${m.id}',tab:'ov',page:null})" title="${esc(m.s===m.n?m.n:m.s+' - '+m.n)}"><span class="ic">${ico(m.id)}</span>${esc(m.bar)}</button>`});
 h+=`<button class="hide" onclick="S.bar=S.bar==='closed'?'open':'closed';render()" title="${col?'Show all modules':'Hide module bar'}" aria-label="Toggle module bar">${ico(col?'chev':'chevu')}</button>`;el.innerHTML=h}
function setCat(k){closeMenus();S.apmCat=k;go({mod:'apm',tab:'ov',page:null})}
const ETABS=[['ov','Overview','edge'],['gw','Gateways','grid'],['dev','Devices & protocols','assets'],['flow','Data flow','ems'],['log','Event log','reports']];
const STABS=[['look','Theme & colours','derms'],['layout','Layout','dash'],['units','Parameter units','pqi'],['data','Add & manage data','assets'],['gen','General','cog']];
function tb(on,act,icon,label,cnt){return `<button class="tabbtn ${on?'on':''}" onclick="${act}" title="${esc(label)}" ${on?'aria-current="page"':''}><span class="ic">${ico(icon)}</span><span class="n">${esc(label)}</span>${cnt?`<span class="cnt">${cnt}</span>`:''}</button>`}
function renderRail(){const el=document.getElementById('rail');el.classList.toggle('mini',S.rail==='mini');const e=edgeInfo();let h='';
 if(S.page==='edge')h=`<div class="rt">Edge Status</div>`+ETABS.map(t=>tb(UI.etab===t[0],`UI.etab='${t[0]}';renderView();renderRail()`,t[2],t[1])).join('');
 else if(S.page==='settings')h=`<div class="rt">Settings</div>`+STABS.map(t=>tb(UI.stab===t[0],`UI.stab='${t[0]}';renderView();renderRail()`,t[2],t[1])).join('');
 else if(S.page==='malerts')h=`<div class="rt">Mobile alerts</div>`+MAT.map(t=>tb(UI.matab===t[0],`UI.matab='${t[0]}';renderView();renderRail()`,t[2],t[1])).join('');
 else if(S.page==='help')h=`<div class="rt">Help & Support</div>`+tb(true,'','help','Help & Support');
 else if(S.page==='profile')h=`<div class="rt">Profile</div>`+tb(true,'','user','Profile');
 else{h=`<div class="rt">${S.mod==='dash'?'Dashboard':S.mod==='apm'?'APM - '+esc(CATB[S.apmCat].short):esc(mod(S.mod).s)}</div>`+tabsOf(S.mod).map(t=>tb(S.tab===t[0]&&!UI.v360,`go({tab:'${t[0]}'})`,t[2],t[1],t[0]==='alarms'?actCount(S.mod):0)).join('')}
 h+=`<div class="grow"></div>${S.page==='edge'?'':`<button class="edge" onclick="go({page:'edge'})" title="${e.txt}"><span class="dot" style="background:${e.color}"></span><span>${e.txt}</span></button>`}<button class="tabbtn collapse" onclick="S.rail=S.rail==='mini'?'full':'mini';render()" title="Collapse"><span class="ic">${ico(S.rail==='mini'?'chevr':'chevl')}</span><span class="n">Collapse</span></button>`;el.innerHTML=h}
function modName(){return S.mod==='dash'?'Dashboard':S.mod==='apm'?'APM - '+CATB[S.apmCat].short:mod(S.mod).s}
function renderSubbar(){const el=document.getElementById('subbar');if(UI.v360||UI.exp){el.style.display='none';return}el.style.display='flex';let left='',right='';
 if(S.page){const T={edge:'Edge Status',settings:'Settings',malerts:'Mobile alerts',help:'Help & Support',profile:'Profile'}[S.page];const st=S.page==='edge'?ETABS.find(x=>x[0]===UI.etab)[1]:S.page==='settings'?STABS.find(x=>x[0]===UI.stab)[1]:S.page==='malerts'?MAT.find(x=>x[0]===UI.matab)[1]:'';left=`<div class="ttl">${T}${st?`<small>${st}</small>`:''}</div>`}
 else if(S.tab==='ov'){const L=subsOf(S.mod),c=curSub(S.mod);left=L.length>1?`<div class="subchips" role="tablist">${L.map(x=>`<button role="tab" aria-selected="${x[0]===c}" class="${x[0]===c?'on':''}" onclick="goSub('${x[0]}')">${esc(x[1])}</button>`).join('')}</div>`:`<div class="ttl">${esc(modName())}</div>`;
  if(S.mod==='dash')right=`<button class="btn ${UI.dsel?'':'ghost'}" onclick="UI.dsel=!UI.dsel;renderView();renderSubbar()">${ico('grid','style="width:14px;height:14px;vertical-align:-3px"')} Choose modules</button>`}
 else{const t=tabsOf(S.mod).find(x=>x[0]===S.tab);left=`<div class="ttl">${t?t[1]:''}<small>${esc(modName())} · ${S.plant}</small></div>`}
 if(!S.page&&S.mod!=='dash'){const T=ADDT[S.mod]||ADDT._;right+=`<div class="dd"><button class="btn" onclick="toggleMenu('mAdd',event)">+ Add</button><div class="menu" id="mAdd" style="min-width:260px" onclick="event.stopPropagation()"><div class="mh"><b>Add to ${esc(modName())}</b><small>Saved to the asset register</small></div>${T.map(t=>`<button class="mi" onclick="openAdd('${t[0]}',{mod:'${S.mod}'})">${ico(FORMS[t[0]].ic||'assets')}${esc(t[1])}</button>`).join('')}<hr><button class="mi" onclick="UI.stab='data';go({page:'settings'})">${ico('reports')}Open asset register</button></div></div>`}
 el.innerHTML=`<div class="sbl">${S.mod==='dash'&&S.tab==='ov'&&!S.page?'<span class="vas">Viewing as</span>':''}${left}</div><div class="sbx">${right}</div>`}
let DT_ACTIVE=false;
function renderView(){const v=document.getElementById('view');UI.xreg={};XID=0;let h='';
 try{if(S.page)h=PAGES[S.page]();else if(UI.exp)h=fsView();else if(UI.v360)h=view360();else if(S.tab==='ov')h=renderModule();else if(S.tab==='assets')h=assetsTab();else if(S.tab==='alarms')h=alarmsTab();else if(S.tab==='reports')h=reportsTab();else if(S.tab==='ai')h=aiTab()}catch(e){console.error(e);h=`<div class="card empty">This view could not load: ${esc(e.message)}</div>`}
 const wantDT=!S.page&&!UI.exp&&!UI.v360&&S.tab==='ov'&&S.mod==='twin'&&curSub('twin')==='3d';if(DT_ACTIVE||DT.r)dtStop();
 v.innerHTML=h;renderSubbar();if(wantDT)dtStart();save()}
function renderModule(){const m=MODV[S.mod];if(!m)return '<div class="empty">Module not available.</div>';return m.view(curSub(S.mod))}
