/* ---------- AI Co-Pilot: the only place with the four AI layer cards ---------- */
const PROMPTS=['Summarise today','Why did it happen?','What will happen next?','What should I do now?','Which assets need attention?','Draft a shift handover note'];
function aiData(){const m=S.mod;if(m==='apm'){if(S.apmCat==='apm')return AIL.apm;const a=UCB[S.apmCat].ai;return [a.d,a.g,a.p,a.r].map(x=>x.slice(0,3))}if(m==='dash')return [0,1,2,3].map(i=>[AIL.dash[i][0]].concat(S.mods.slice(0,2).map(id=>(id==='apm'?'APM: ':mod(id).s+': ')+(AIL[id]||AIL.dash)[i][0])));return AIL[m]||AIL.dash}
function aiTab(){const L=aiData();const nm=modName();const k=S.mod+(S.mod==='apm'?S.apmCat:'');const ctx=UI.aiAsset?findA(UI.aiAsset):null;
 const c=UI.chat[k]||(UI.chat[k]=[{b:1,t:`Hello, I'm CoreOT Co-Pilot for ${nm} at ${S.plant}. The four layers above refresh from live data. Ask me anything below.`}]);
 return fit(`<div class="ai4 auto">${AIC.map((a,i)=>`<div class="aic3"><h4 style="background:var(${a[1]})">${a[0]}<span>${a[2]}</span></h4><ul>${L[i].map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="aif"><span>${i<3?'Confidence':'Impact'}</span><b>${['96%','88%','81%','High'][i]}</b>${i===3?`<button class="btn sm ghost" onclick="toast('Action plan shared with the team')">Create tasks</button>`:''}</div></div>`).join('')}</div>`,
 row('1fr',[`<div class="card"><div class="ch"><h3>Ask CoreOT Co-Pilot</h3><div class="fchips"><span class="chip c-idle">${S.plant}</span><span class="chip c-idle">${esc(nm)}</span>${ctx?`<span class="chip c-info">${esc(ctx.n)}</span><button class="lnk" onclick="UI.aiAsset=null;renderView()">clear</button>`:''}</div><button class="btn sm ghost" onclick="UI.chat['${k}']=null;renderView()">New chat</button></div><div class="chat" id="chat" aria-live="polite">${c.map(m=>`<div class="msg ${m.b?'b':'u'}">${esc(m.t)}</div>`).join('')}</div><div class="fchips" style="margin-top:8px">${PROMPTS.map((p,i)=>`<button class="fchip" onclick="askAI(${i})">${p}</button>`).join('')}</div><div class="ask"><input id="q" placeholder="Ask about ${esc(nm)}" onkeydown="if(event.key==='Enter')askAI()"><button class="btn" onclick="askAI()" aria-label="Send">${ico('send')}</button></div></div>`]))}
function askAI(i,txt){const L=aiData();const k=S.mod+(S.mod==='apm'?S.apmCat:'');if(!UI.chat[k])aiTab();const c=UI.chat[k];const al=alarmsFor(S.mod).filter(x=>x.st==='Active');let qx,a;
 if(txt){qx=txt;const A=UI.aiAsset?findA(UI.aiAsset):null;if(A){const bad=A.ps.filter(p=>rdState(p)==='bad');a=`${A.n} is ${A.st.toLowerCase()}${A.hl?' with a '+A.hl.toLowerCase()+' health flag':''}, health score ${A.health}. Key readings: ${A.ps.slice(0,3).map(p=>p[0]+' '+conv(p[1],p[2]).join(' ')).join(', ')}. ${bad.length?'Out of range: '+bad.map(p=>p[0]).join(', ')+'. Inspect at the next stop.':'All readings are inside their normal range.'}`}else a=L[0].join(' ')}
 else if(i!=null){qx=PROMPTS[i];a=i<4?L[i].join(' '):i===4?(al.length?'Needs attention now: '+al.slice(0,4).map(x=>`${x.a} (${x.sev.toLowerCase()}): ${x.msg}`).join('; ')+'.':'Nothing needs attention right now.'):`Shift handover, ${S.plant}. Status: ${L[0][0]} Open: ${al.slice(0,3).map(x=>x.a+' - '+x.msg).join('; ')||'none'}. Watch: ${L[2][0]} Do: ${L[3][0]}`}
 else{const el=document.getElementById('q');qx=el.value.trim();if(!qx)return;const ql=qx.toLowerCase();a=/why|cause/.test(ql)?L[1].join(' '):/next|forecast|will|predict/.test(ql)?L[2].join(' '):/do|action|fix|should|recommend/.test(ql)?L[3].join(' '):L[0][0]+' '+L[3][0]}
 c.push({t:qx});renderView();setTimeout(()=>{c.push({b:1,t:a});renderView();const ch=document.getElementById('chat');if(ch)ch.scrollTop=ch.scrollHeight},400)}

