const REGK='coreot-r8n-register';
function regAll(){try{return JSON.parse(localStorage.getItem(REGK)||'[]')}catch(e){return []}}
function regSave(L){try{localStorage.setItem(REGK,JSON.stringify(L))}catch(e){toast('Could not save on this device')}}
function idb(){return new Promise((res,rej)=>{try{const r=indexedDB.open('coreot-r8n',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
async function fput(id,v){const db=await idb();return new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(v,id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function fget(id){const db=await idb();return new Promise((res,rej)=>{const t=db.transaction('files');const r=t.objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function fdel(id){try{const db=await idb();db.transaction('files','readwrite').objectStore('files').delete(id)}catch(e){}}
function daysTo(d){return Math.round((new Date(d+'T00:00:00')-new Date(new Date().toDateString()))/864e5)}
function coRecs(qq){return regAll().filter(r=>(!qq.type||r.type===qq.type)&&(!qq.mod||r.mod===qq.mod)&&(!qq.asset||(r.f.asset||r.f.name||'')===qq.asset))}
let ADDCTX=null;
function openAdd(type,ctx){closeMenus();const fm=FORMS[type];if(!fm)return;ADDCTX={type,mod:(ctx&&ctx.mod)||S.mod,pre:ctx||{}};const m=ADDCTX.mod;
 const names=[...new Set((m&&m!=='edge'&&m!=='dash'?assetsOf(m).map(a=>a.n):[]).concat(regAll().filter(r=>r.type==='asset'&&r.mod===m).map(r=>r.f.name)))];
 const inp=x=>{const id='af-'+x.k,pv=ADDCTX.pre[x.k]||'',rq=x.req?' required':'';
  if(x.t==='select'){const o=x.o==='GWS'?gwList().map(g=>g.id):x.o==='USES'?USES.map(u=>u[1]):x.o;return `<select id="${id}" class="fin"${rq}>${o.map(v=>`<option ${v===pv?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
  if(x.t==='assetsel')return `<input id="${id}" class="fin" list="${id}-l" value="${esc(pv)}" placeholder="Pick or type an asset"${rq}><datalist id="${id}-l">${names.map(n=>`<option value="${esc(n)}">`).join('')}</datalist>`;
  if(x.t==='textarea')return `<textarea id="${id}" class="fin" rows="3">${esc(pv)}</textarea>`;
  if(x.t==='file'||x.t==='files')return `<input id="${id}" type="file" class="fin" accept="${x.o||''}" ${x.t==='files'?'multiple':''}${rq}><small style="font-size:11px">Up to 8 MB each, stored on this device in the demo.</small>`;
  return `<input id="${id}" type="${x.t}" class="fin" value="${esc(pv)}"${rq}>`};
 openModal(`<div class="ch"><h3>${fm.t}</h3><span class="chip c-idle">${esc(m==='edge'?'Edge Status':m==='dash'?'Dashboard':modName())}</span><button class="xb" onclick="closeModal()" aria-label="Close">${ico('x')}</button></div><form class="af" onsubmit="event.preventDefault();saveAdd()">${fm.f.map(x=>`<label class="${/textarea|file/.test(x.t)?'wide':''}"><span>${esc(x.l)}${x.req?' *':''}</span>${inp(x)}</label>`).join('')}<div class="afb wide"><button type="button" class="btn ghost" onclick="closeModal()">Cancel</button><button type="submit" class="btn">Save</button></div></form>`,true)}
function readFile(f){return new Promise((res,rej)=>{if(f.size>8*1024*1024){rej(new Error(f.name+' is larger than 8 MB'));return}const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(f)})}
async function saveAdd(){const c=ADDCTX;if(!c)return;const fm=FORMS[c.type];const f={},files=[];
 for(const x of fm.f){const el=document.getElementById('af-'+x.k);if(!el)continue;if(/file/.test(x.t)){for(const fl of el.files){try{const data=await readFile(fl);const id='f'+Date.now()+Math.random().toString(36).slice(2,7);await fput(id,{name:fl.name,type:fl.type,size:fl.size,data});files.push({id,name:fl.name,type:fl.type,size:fl.size,field:x.k})}catch(e){toast(e.message||'File could not be stored');return}}}else f[x.k]=el.value.trim()}
 const L=regAll();const rec={id:'r'+Date.now(),type:c.type,mod:c.mod,cat:c.mod==='apm'?S.apmCat:null,plant:S.plant,f,files,at:new Date().toISOString()};L.unshift(rec);
 if(['asset','der','vehicle'].includes(c.type))files.filter(x=>x.field==='docs').forEach(x=>L.unshift({id:'r'+Date.now()+x.id,type:'doc',mod:c.mod,cat:rec.cat,plant:S.plant,f:{asset:f.name,dtype:'Other',title:x.name},files:[x],at:rec.at}));
 regSave(L);closeModal();toast(fm.t.replace(/^Add |^Upload /,'')+' saved');if(c.type==='glb'&&files[0])dtLoadGLB(files[0].id);renderView()}
function regDel(id){const L=regAll();const r=L.find(x=>x.id===id);if(r)(r.files||[]).forEach(x=>fdel(x.id));regSave(L.filter(x=>x.id!==id));toast('Removed');renderView()}
async function regView(id){const r=regAll().find(x=>x.id===id);if(!r)return;const fm=FORMS[r.type]||{t:r.type,f:[]};let prev='';
 for(const x of (r.files||[])){try{const v=await fget(x.id);if(v&&/^image\//.test(v.type))prev+=`<figure style="margin:0;width:180px"><img src="${v.data}" alt="${esc(v.name)}" style="width:100%;border-radius:12px;border:1px solid var(--line)"><figcaption style="font-size:11px;color:var(--mut)">${esc(v.name)}</figcaption></figure>`;else prev+=`<div class="sbr" style="width:auto">${ico('doc')}<span class="st"><b>${esc(x.name)}</b><small>${(x.size/1024).toFixed(0)} kB on this device</small></span></div>`}catch(e){}}
 openModal(`<div class="ch"><h3>${esc(r.f.name||r.f.title||r.f.item||r.f.code||fm.t)}</h3><span class="chip c-idle">${esc(fm.t.replace(/^Add |^Upload /,''))}</span><button class="xb" onclick="closeModal()">${ico('x')}</button></div><div class="kv3">${fm.f.filter(x=>!/file/.test(x.t)&&r.f[x.k]).map(x=>`<div><small>${esc(x.l)}</small><b>${esc(r.f[x.k])}</b></div>`).join('')}<div><small>Added</small><b>${new Date(r.at).toLocaleString('en-IN')}</b></div></div>${prev?`<div class="h5">Files</div><div style="display:flex;gap:10px;flex-wrap:wrap">${prev}</div>`:''}`,true)}
function registerView(){const L=regAll();const nm=r=>r.f.name||r.f.title||r.f.item||r.f.code||r.f.ledger||'(no name)';
 return fit(row('1fr',[gcard('Asset register and documents',`<p class="note" style="margin-top:0">Everything added from + Add in any module or View 360 lands here. Documents linked to an asset show in its View 360 with expiry status. In a live deployment these save to the CoreOT Platform; in this demo they stay on this device.</p>`+(L.length?tbl(['Name','Type','Module','Linked asset','Expiry','Files','Added',''],L.map(r=>[`<button class="lnk" onclick="regView('${r.id}')">${esc(nm(r))}</button>`,esc((FORMS[r.type]||{t:r.type}).t.replace(/^Add |^Upload /,'')),r.mod==='edge'?'Edge':r.mod==='dash'?'Dashboard':esc((mod(r.mod)||{}).s||r.mod),esc(r.f.asset||r.f.parent||'-'),r.f.expiry||'-',(r.files||[]).length,new Date(r.at).toLocaleDateString('en-GB'),`<button class="btn sm ghost" onclick="regDel('${r.id}')">Remove</button>`])):'<div class="empty">Nothing added yet. Try + Add in any module, or add a warranty card from an asset\'s View 360.</div>'),{extra:`<button class="btn sm" onclick="openAdd('asset',{mod:'apm'})">+ Add asset</button><button class="btn sm ghost" onclick="openAdd('doc',{mod:'apm'})">+ Add document</button>`})]))}

