function bigK(t,v,u,d,desc,col,seed){const up=d>=0;return `<div class="card" style="position:relative;overflow:hidden;padding-bottom:6px"><div class="ch" style="margin-bottom:2px"><h3>${t}</h3><span class="chip ${(col==='crit'?!up:up)?'c-crit':'c-ok'}">${up?'▲':'▼'} ${Math.abs(d)}%</span></div><div style="display:flex;align-items:flex-end;gap:10px;flex:1;min-height:0"><div style="flex:none"><div class="big" style="font-size:30px">${v}<span style="font-size:14px;color:var(--mut);font-weight:600"> ${u}</span></div><div class="note" style="margin:4px 0 6px;max-width:220px">${desc}</div></div><svg viewBox="0 0 200 60" preserveAspectRatio="none" style="flex:1;height:64px;align-self:flex-end">${(()=>{const s=series(seed,14,30,14);const mx=Math.max(...s),mn=Math.min(...s);const pts=s.map((x,i)=>[i*200/13,58-(x-mn)/(mx-mn||1)*48]);const dd=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');const c=col==='crit'?'var(--crit)':col==='ok'?'var(--ok)':'var(--brand)';return `<path d="${dd} L200 60 L0 60Z" fill="${c}" opacity=".15"/><path d="${dd}" fill="none" stroke="${c}" stroke-width="2"/>`})()}</svg></div></div>`}
