function evCard(m,n=5){const k='ev'+m;const tab=UI[k]||'act';const act=alarmsFor(m).filter(a=>a.st==='Active');const ev=alarmsFor(m).filter(a=>a.st!=='Active').map(a=>({t:a.t,a:a.a,msg:'Acknowledged: '+a.msg,sev:'Acknowledged'})).concat(EVTS.slice(0,4).map((e,i)=>({t:['08:00','07:30','07:05','06:00'][i],a:'System',msg:e,sev:'Info'})));
 const body=tab==='act'?alarmRows(m,n):`<div class="rows">${ev.slice(0,n+1).map(x=>`<div class="rw"><div class="a"><b>${esc(x.a)}</b><small>${esc(x.msg)}</small></div><span class="v" style="font-size:11px;color:var(--mut)">${x.t}</span>${chip(x.sev)}</div>`).join('')}</div>`;
 return gcard('Alarms & Events',body,{x:false,extra:`<span class="seg"><button class="${tab==='act'?'on':''}" onclick="UI['${k}']='act';renderView()">Active ${act.length}</button><button class="${tab==='ev'?'on':''}" onclick="UI['${k}']='ev';renderView()">Events</button></span><button class="lnk" onclick="go({tab:'alarms'})">View all</button>`})}
