const FAREA={tank:'Storage & suppression',gas:'Storage & suppression',ext:'Storage & suppression',pump:'Pump house',jky:'Pump house',bst:'Pump house',dsl:'Pump house',pnl:'Pump house',hyd:'Hydrant network',hose:'Hydrant network',mon:'Hydrant network',spr:'Sprinkler zones',facp:'Detection & alarm',smk:'Detection & alarm',heat:'Detection & alarm'};
function treeData(){const A=assetsOf(S.mod);const area=a=>S.mod==='apm'?(a.fid?FAREA[a.fid]||'General':CATB[S.apmCat].short+' area'):a.loc||mod(S.mod).s;const T={};A.forEach((a,i)=>{const ar=area(a);const ln=S.mod==='apm'&&a.fid?'':('Line '+(1+Math.floor(i/3)));((T[ar]=T[ar]||{})[ln]=T[ar][ln]||[]).push(a)});return T}
