/* ---------- 4. images: save as PNG, print to PDF ---------- */
const bgOf=()=>{const s=getComputedStyle(document.body);return s.backgroundColor&&s.backgroundColor!=='rgba(0, 0, 0, 0)'?s.backgroundColor:(S.theme==='dark'?'#17150f':'#fbf6e8')};
async function snapImg(el,kind){if(!window.htmlToImage){toast('Image capture is not available here');return null}const opt={pixelRatio:2,backgroundColor:getComputedStyle(el).backgroundColor&&getComputedStyle(el).backgroundColor!=='rgba(0, 0, 0, 0)'?getComputedStyle(el).backgroundColor:bgOf(),filter:n=>!(n.classList&&(n.classList.contains('cmbtn')||n.classList.contains('cmmenu'))),cacheBust:false,skipFonts:true};try{return kind==='jpeg'?await htmlToImage.toJpeg(el,{...opt,quality:.92}):await htmlToImage.toPng(el,opt)}catch(e){console.warn(e);toast('Could not capture this card');return null}}
const dataUrlBytes=u=>{const b=atob(u.split(',')[1]);const a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a};
async function saveImage(el,title){toast('Preparing image…');const u=await snapImg(el,'png');if(!u)return;await dlFile(fname(title||'CoreOT','png'),new Blob([dataUrlBytes(u)],{type:'image/png'}));trail('Saved image',title||'')}
async function printPdf(el,title){toast('Preparing PDF…');const u=await snapImg(el,'jpeg');if(!u)return;const img=new Image();await new Promise(r=>{img.onload=r;img.src=u});await dlFile(fname(title||'CoreOT','pdf'),pdfImage(title||'CoreOT',dataUrlBytes(u),img.naturalWidth,img.naturalHeight));trail('Printed to PDF',title||'')}
/* ---------- 5. card menu on every card, KPI row and chart ---------- */
