function cmOpen(btn,ev){ev&&ev.stopPropagation();closeMenus();document.querySelectorAll('.cmmenu').forEach(m=>m.remove());const host=btn.closest('.card,.tiles,.krfsw')||btn.parentNode;CMT=host;const ttl=(host.querySelector('.ch h3')?ctext(host.querySelector('.ch h3')):host.classList.contains('tiles')?'KPI cards':'Card');const hasData=!!(host.querySelector('table,.ich,.krc3,.hb,.tile,.rows>.rw,.kv3,.idg,.tl,.woc')||ctext(host).length>2);
 const m=document.createElement('div');m.className='cmmenu';m.innerHTML=`<div class="mh"><b>${esc(ttl)}</b><small>Download or capture this card</small></div>${hasData?`<button class="mi" onclick="cmDo('xlsx')">${ico('reports')}Download Excel (.xlsx)</button><button class="mi" onclick="cmDo('csv')">${ico('reports')}Download CSV</button><button class="mi" onclick="cmDo('pdf')">${ico('doc')}Download PDF (data)</button><hr>`:''}<button class="mi" onclick="cmDo('png')">${ico('camera')}Save as image (PNG)</button><button class="mi" onclick="cmDo('print')">${ico('doc')}Print / save as PDF</button>`;document.body.appendChild(m);const r=btn.getBoundingClientRect();const mw=250;m.style.left=Math.max(8,Math.min(window.innerWidth-mw-8,r.right-mw))+'px';m.style.top=Math.min(window.innerHeight-260,r.bottom+6)+'px';setTimeout(()=>document.addEventListener('click',cmClose,{once:true}),0)}
