function exportMenu(btn,ev){ev.stopPropagation();closeMenus();document.querySelectorAll('.cmmenu').forEach(m=>m.remove());const m=document.createElement('div');m.className='cmmenu';m.innerHTML=`<div class="mh"><b>Export this view</b><small>Every card on this screen</small></div><button class="mi" onclick="cmClose();exportView('xlsx')">${ico('reports')}Excel, one sheet per card</button><button class="mi" onclick="cmClose();exportView('csv')">${ico('reports')}CSV</button><button class="mi" onclick="cmClose();exportView('pdf')">${ico('doc')}PDF (data)</button><hr><button class="mi" onclick="cmClose();exportView('png')">${ico('camera')}Save screen as image (PNG)</button><button class="mi" onclick="cmClose();exportView('print')">${ico('doc')}Print screen / save as PDF</button>`;document.body.appendChild(m);const r=btn.getBoundingClientRect();m.style.left=Math.max(8,Math.min(window.innerWidth-258,r.right-250))+'px';m.style.top=(r.bottom+6)+'px';setTimeout(()=>document.addEventListener('click',cmClose,{once:true}),0)}
