function liveRows(a,j){const k=a.id+(j!=null?'#'+j:'');const sel=krSel(a,j);return [['Parameter','Value','Unit','Tag','Low limit','High limit','Alarm','Show on Overview']].concat(fullPs(a,j).map(p=>{const key=k+'|'+p[0];const c=conv(p[1],p[2],key);const lim=(S.klim&&S.klim[key])||{};return [p[0],c[0],c[1]||'',tagOf(a,j,p),p[3]==null?'':conv(p[3],p[2],key)[0],p[4]==null?'':conv(p[4],p[2],key)[0],lim.al===0?'Off':'On',sel.includes(p[0])?'Yes':'No']}))}
function liveDL(id,j,f){const a=findA(id);const nm=(j!=null?subOf(a,j).n+' - ':'')+a.n+' live data';exportSheets(nm,[{name:'Live data',rows:liveRows(a,j)}],f||'xlsx');trail('Downloaded live data',nm)}
function liveUL(id,j,inp){const f=inp.files&&inp.files[0];if(!f)return;const a=findA(id);const k=a.id+(j!=null?'#'+j:'');readSheet(f).then(rows=>{const hd=(rows[0]||[]).map(h=>String(h).toLowerCase().trim());const col=n=>hd.findIndex(h=>h===n);const ip=col('parameter'),it=col('tag'),iu=col('unit'),il=col('low limit'),ih=col('high limit'),ia=col('alarm'),is=col('show on overview');if(ip<0){toast('Missing "Parameter" column');return}
 const P2=fullPs(a,j).map(p=>p[0]);let n=0;const show=[];rows.slice(1).forEach(r=>{const nm=String(r[ip]||'').trim();if(!P2.includes(nm))return;n++;const key=k+'|'+nm;if(it>=0&&r[it])S.ktag[key]=String(r[it]);if(iu>=0&&r[iu]){const g=ugOf(fullPs(a,j).find(p=>p[0]===nm)[2]);if(g&&UG[g].u.includes(String(r[iu])))S.ku[key]=String(r[iu])}const L=S.klim[key]=S.klim[key]||{};if(il>=0&&r[il]!==''&&r[il]!=null)L.lo=String(r[il]);if(ih>=0&&r[ih]!==''&&r[ih]!=null)L.hi=String(r[ih]);if(ia>=0&&r[ia])L.al=/^(off|no|0|false)$/i.test(String(r[ia]))?0:1;if(is>=0&&/^(yes|y|1|true)$/i.test(String(r[is]).trim()))show.push(nm)});
 if(is>=0)S.krs[k]=show;save();trail('Uploaded live data',a.n+' ('+n+' parameters)');toast(`${n} parameters updated from ${f.name}`);inp.value='';renderView();if(UI.panel)renderPanel()}).catch(e=>{toast('Could not read the file: '+(e.message||e))})}
const liveBtns=(a,j)=>`<button class="btn sm ghost" onclick="liveDL('${a.id}',${j==null?'null':j},'xlsx')">${ico('reports','style="width:12px;height:12px;vertical-align:-2px"')} Download Excel</button><label class="btn sm ghost" style="cursor:pointer">${ico('plus','style="width:12px;height:12px;vertical-align:-2px"')} Upload Excel<input type="file" accept=".xlsx,.csv" hidden onchange="liveUL('${a.id}',${j==null?'null':j},this)"></label>`;
