if(typeof chkView==='function'){const _cv=chkView;chkView=function(){const k=ucOf('chk');const H=UI.chk.map((x,i)=>[x,i]).filter(x=>x[0].k===k);let h=_cv();if(H.length)h=h.replace(/(<h3>Completed checklists<\/h3>)/,`$1<span class="spacer"></span>${H.slice(0,3).map(([x,i])=>`<button class="btn sm ghost" onclick="chkPDF(${i})" title="${esc(x.n)}">PDF ${x.t}</button>`).join('')}`);return h}}
