function pdmDL(id){const a=findA(id);const R=rel(a);const W=typeof woFor==='function'&&!isBasic()?woFor(a.id):[];const sheets=[{name:'Reliability',rows:[['Metric','Value'],['Health',a.health],['MTBF (h)',R.mtbf],['MTTR (h)',R.mttr],['Failures, 12 months',R.fail],['Remaining useful life (d)',R.rul],['Availability (%)',R.avail],['Failure risk, 30 days (%)',R.pfail]]},{name:'Health 30 days',rows:[['Day','Health']].concat(series('h30'+a.n,30,a.health+4,4).map((v,i)=>[i+1,v]))},{name:'Spares',rows:[['Part number','Spare','Qty','In stock','Bin','Status']].concat(bomOf(a))}];if(W.length)sheets.push({name:'Work orders',rows:[['Work order','Title','Type','Priority','Status','Due','Assigned to']].concat(W.map(w=>[w.id,w.t,w.type,w.pri,w.st,w.due,w.who]))});if(!isBasic())sheets.push({name:'Predictive triggers',rows:[['Task','Trigger','Role','Duration','Spares']].concat(a.subs.slice(0,5).map((s,j)=>[`Inspect ${s.n.toLowerCase()}`,`${s.par} ${j%2?'trend up 3 days':'beyond limit'}`,['Mechanical','Electrical','Instrument','Operator'][j%4],(1+j%3)+' h',bomOf(a)[j]?bomOf(a)[j][1]:'-'])) });exportSheets(a.n+' maintenance data',sheets,'xlsx');trail('Downloaded maintenance data',a.n)}

